def text_to_series(apps, schema_editor):
    """Each distinct series text (ignoring case and surrounding spaces) becomes a Series,
    named as most games spell it; games get theirs linked."""
    Work = apps.get_model("catalog", "Work")
    Series = apps.get_model("catalog", "Series")
    spellings: dict[str, Counter[str]] = {}
    for text in Work.objects.exclude(series="").values_list("series", flat=True):
        name = " ".join(text.split())
        if name:
            spellings.setdefault(name.lower(), Counter())[name] += 1
    by_key = {
        key: Series.objects.create(name=counts.most_common(1)[0][0])
        for key, counts in spellings.items()
    }
    for work in Work.objects.exclude(series=""):
        key = " ".join(work.series.split()).lower()
        if key in by_key:
            work.series_set.add(by_key[key])


def series_to_text(apps, schema_editor):
    Work = apps.get_model("catalog", "Work")
    for work in Work.objects.prefetch_related("series_set"):
        names = sorted(s.name for s in work.series_set.all())
        if names:
            work.series = names[0][:200]
            work.save(update_fields=["series"])


